head.b:skin:
/* Blogger Required Reset */
body {
  margin: 0;
  padding: 0;
  background-color: #f3f4f6;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: #1f2937;
  line-height: 1.5;
}

* { box-sizing: border-box; }

:root {
  --primary-color: #0f172a;
  --accent-color: #2563eb;
  --bg-slate: #f8fafc;
  --border-color: #e2e8f0;
  --sidebar-width: 520px;
}

body {
  background-color: #f1f5f9;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.blogger-hidden-section { display: none !important; }

/* Header */
.app-header {
  background: #0f172a;
  color: #ffffff;
  padding: 0.75rem 1.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
  position: sticky;
  top: 0;
  z-index: 50;
}

.app-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-weight: 700;
  font-size: 1.25rem;
  color: #ffffff;
  text-decoration: none;
}

.app-brand i { color: #38bdf8; font-size: 1.5rem; }

.domain-badge {
  font-size: 0.75rem;
  background: rgba(56, 189, 248, 0.2);
  color: #38bdf8;
  padding: 2px 8px;
  border-radius: 12px;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.header-actions { display: flex; align-items: center; gap: 0.5rem; flex-wrap: wrap; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 0.85rem;
  font-size: 0.85rem;
  font-weight: 500;
  border-radius: 0.375rem;
  border: 1px solid transparent;
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.btn-primary { background-color: #2563eb; color: #ffffff; }
.btn-primary:hover { background-color: #1d4ed8; }

.btn-success { background-color: #10b981; color: #ffffff; }
.btn-success:hover { background-color: #059669; }

.btn-secondary { background-color: #475569; color: #ffffff; }
.btn-secondary:hover { background-color: #334155; }

.btn-outline { background-color: transparent; border-color: #cbd5e1; color: #334155; }
.btn-outline:hover { background-color: #f1f5f9; border-color: #94a3b8; }

.btn-outline-dark { background-color: transparent; border-color: #334155; color: #e2e8f0; }
.btn-outline-dark:hover { background-color: #1e293b; color: #ffffff; }

.btn-danger { background-color: #ef4444; color: #ffffff; }
.btn-danger:hover { background-color: #dc2626; }

.btn-sm { padding: 0.25rem 0.5rem; font-size: 0.75rem; }

/* Container */
.app-container {
  display: flex;
  flex: 1;
  height: calc(100vh - 57px);
  overflow: hidden;
}

.editor-panel {
  width: var(--sidebar-width);
  min-width: 360px;
  max-width: 600px;
  background: #ffffff;
  border-right: 1px solid #e2e8f0;
  display: flex;
  flex-direction: column;
  height: 100%;
  z-index: 20;
}

.editor-tabs {
  display: flex;
  overflow-x: auto;
  background: #f8fafc;
  border-bottom: 1px solid #e2e8f0;
  scrollbar-width: thin;
}

.editor-tab-btn {
  padding: 0.75rem 0.9rem;
  font-size: 0.825rem;
  font-weight: 600;
  color: #64748b;
  border: none;
  background: transparent;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  white-space: nowrap;
  transition: all 0.2s;
}

.editor-tab-btn:hover { color: #2563eb; background: #f1f5f9; }
.editor-tab-btn.active { color: #2563eb; border-bottom-color: #2563eb; background: #ffffff; }

.editor-content { flex: 1; overflow-y: auto; padding: 1.25rem; }
.tab-pane { display: none; }
.tab-pane.active { display: block; }

.section-title {
  font-size: 1.05rem;
  font-weight: 700;
  color: #0f172a;
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 2px solid #e2e8f0;
  padding-bottom: 0.5rem;
}

.form-group { margin-bottom: 1rem; }
.form-row { display: flex; gap: 0.75rem; }
.form-row .form-group { flex: 1; }

label { display: block; font-size: 0.8rem; font-weight: 600; color: #334155; margin-bottom: 0.35rem; }

input[type="text"], input[type="email"], input[type="tel"], input[type="url"], input[type="date"], input[type="month"], select, textarea {
  width: 100%;
  padding: 0.5rem 0.75rem;
  font-size: 0.875rem;
  border: 1px solid #cbd5e1;
  border-radius: 0.375rem;
  background-color: #ffffff;
  color: #0f172a;
}

input:focus, select:focus, textarea:focus {
  outline: none;
  border-color: #2563eb;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}

textarea { resize: vertical; min-height: 80px; }

.checkbox-group { display: flex; align-items: center; gap: 0.5rem; margin-top: 0.5rem; }
.checkbox-group label { margin-bottom: 0; font-weight: 400; cursor: pointer; }

.entry-card {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 0.5rem;
  padding: 1rem;
  margin-bottom: 1rem;
}

.entry-card-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.75rem; }
.entry-card-title { font-weight: 600; font-size: 0.9rem; color: #334155; }
.entry-actions { display: flex; gap: 0.25rem; }

.color-swatches { display: flex; gap: 0.4rem; align-items: center; margin-top: 0.35rem; }
.swatch {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  cursor: pointer;
  border: 2px solid #ffffff;
  box-shadow: 0 0 0 1px #cbd5e1;
  transition: transform 0.15s ease;
}
.swatch:hover { transform: scale(1.15); }

/* Right Preview Panel */
.preview-panel {
  flex: 1;
  background: #334155;
  overflow-y: auto;
  padding: 2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.preview-toolbar {
  background: #ffffff;
  padding: 0.6rem 1.25rem;
  border-radius: 0.5rem;
  margin-bottom: 1.5rem;
  display: flex;
  align-items: center;
  gap: 1.25rem;
  box-shadow: 0 4px 6px -1px rgba(0,0,0,0.15);
  flex-wrap: wrap;
}

.toolbar-group {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.85rem;
  font-weight: 600;
  color: #334155;
}

.toolbar-group select, .toolbar-group input[type="color"] {
  padding: 0.25rem 0.5rem;
  border-radius: 0.25rem;
  border: 1px solid #cbd5e1;
  height: 32px;
}

.toolbar-group input[type="color"] { width: 36px; padding: 2px; cursor: pointer; }

.resume-paper {
  background: #ffffff;
  width: 210mm;
  min-height: 297mm;
  box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3);
  position: relative;
  margin: 0 auto;
  box-sizing: border-box;
}

.mobile-view-toggle {
  display: none;
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 100;
  border-radius: 50px;
  padding: 0.75rem 1.25rem;
  box-shadow: 0 10px 15px -3px rgba(0,0,0,0.3);
}

@media (max-width: 992px) {
  .app-container { flex-direction: column; height: auto; overflow: visible; }
  .editor-panel { width: 100%; max-width: 100%; height: auto; }
  .preview-panel { width: 100%; padding: 1rem 0.5rem; }
  .resume-paper { width: 100%; max-width: 210mm; min-height: auto; }
  .mobile-view-toggle { display: inline-flex; }
}

/* RESUME TEMPLATES STYLING */
.template-modern { display: flex; min-height: 297mm; }
.template-modern .sidebar { width: 32%; background-color: var(--accent-color, #2563eb); color: #ffffff; padding: 2rem 1.25rem; }
.template-modern .main-content { width: 68%; padding: 2rem 1.5rem; }
.template-modern .profile-img { width: 120px; height: 120px; border-radius: 50%; object-fit: cover; margin: 0 auto 1.25rem auto; display: block; border: 3px solid rgba(255,255,255,0.3); }

.template-classic { padding: 2.5rem; }
.template-classic .header-classic { text-align: center; border-bottom: 2px solid var(--accent-color, #1e293b); padding-bottom: 1.25rem; margin-bottom: 1.5rem; }
.template-classic .name-classic { font-size: 2.2rem; font-weight: 700; color: var(--accent-color, #1e293b); text-transform: uppercase; letter-spacing: 0.05em; }

.template-minimal { padding: 2.5rem; }
.template-minimal .header-minimal { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 2rem; border-bottom: 1px solid #e2e8f0; padding-bottom: 1.5rem; }

.template-creative .banner { background: var(--accent-color, #2563eb); color: #ffffff; padding: 2.5rem 2rem; display: flex; align-items: center; gap: 1.5rem; }
.template-creative .banner-img { width: 110px; height: 110px; border-radius: 12px; object-fit: cover; border: 3px solid #ffffff; }

.template-compact { padding: 1.75rem; font-size: 0.85rem; }

.template-executive { padding: 2.5rem; border-top: 8px solid var(--accent-color, #0f172a); }
.template-executive .exec-header { display: flex; align-items: center; justify-content: space-between; border-bottom: 2px solid #e2e8f0; padding-bottom: 1.5rem; margin-bottom: 1.5rem; }

.template-serif { padding: 3rem; font-family: 'Merriweather', 'Lora', serif; line-height: 1.6; }
.template-serif .serif-header { text-align: center; margin-bottom: 2rem; }
.template-serif .serif-title { font-size: 2.2rem; font-weight: 700; color: var(--accent-color, #1e293b); }

.template-timeline { padding: 2.5rem; }
.template-timeline .timeline-item { position: relative; padding-left: 1.5rem; border-left: 2px solid var(--accent-color, #2563eb); margin-bottom: 1.25rem; }
.template-timeline .timeline-dot { position: absolute; left: -6px; top: 4px; width: 10px; height: 10px; border-radius: 50%; background: var(--accent-color, #2563eb); }

@media print {
  body { background: #ffffff !important; margin: 0 !important; padding: 0 !important; }
  .app-header, .editor-panel, .preview-toolbar, .mobile-view-toggle, .blogger-hidden-section { display: none !important; }
  .app-container { height: auto !important; display: block !important; }
  .preview-panel { background: transparent !important; padding: 0 !important; margin: 0 !important; width: 100% !important; }
  .resume-paper { box-shadow: none !important; width: 100% !important; margin: 0 !important; padding: 0 !important; page-break-after: avoid; }
}

body.script:
//

let resumeData = {
  personal: { fullName: '', jobTitle: '', email: '', phone: '', location: '', website: '', photo: '' },
  summary: '',
  experience: [],
  education: [],
  skills: [],
  projects: [],
  languages: [],
  certifications: [],
  socials: [],
  references: [],
  hobbies: [],
  customSections: [],
  settings: { template: 'modern', accentColor: '#2563eb', fontFamily: 'Inter', fontSize: '14px', margin: 'normal' }
};

const sampleData = {
  personal: {
    fullName: 'Alex Morgan',
    jobTitle: 'Lead Software Engineer & Architect',
    email: 'alex.morgan@goodbuilder.cv',
    phone: '+1 (555) 234-5678',
    location: 'San Francisco, CA',
    website: 'https://goodbuilder.cv/alexmorgan',
    photo: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=300'
  },
  summary: 'Results-driven Lead Software Engineer with over 8 years of expertise in designing high-throughput microservices, web applications, and cloud-native solutions on Good Builder CV platform.',
  experience: [
    {
      id: 'exp1',
      title: 'Lead Full-Stack Engineer',
      company: 'TechCorp Solutions',
      location: 'San Francisco, CA',
      startDate: '2021-03',
      endDate: '',
      current: true,
      description: '• Spearheaded migration of monolithic core application into Kubernetes microservices, reducing cloud latency by 42%.\n• Managed a team of 8 engineers delivering modern React and Node.js backend systems.'
    },
    {
      id: 'exp2',
      title: 'Senior Software Developer',
      company: 'InnoTech Labs',
      location: 'Austin, TX',
      startDate: '2018-06',
      endDate: '2021-02',
      current: false,
      description: '• Architected automated CI/CD pipelines cutting release cycles from weeks to hours.\n• Developed real-time data analytics dashboard consumed by over 50,000 daily active clients.'
    }
  ],
  education: [
    {
      id: 'edu1',
      degree: 'B.S. in Computer Science',
      institution: 'University of California, Berkeley',
      location: 'Berkeley, CA',
      startDate: '2014-08',
      endDate: '2018-05',
      gpa: '3.9 / 4.0',
      description: 'Graduated with Highest Honors. Coursework focused on Distributed Systems, Algorithms, and Software Engineering.'
    }
  ],
  skills: [
    { id: 'sk1', name: 'JavaScript / TypeScript', level: '95', category: 'Frontend' },
    { id: 'sk2', name: 'React / Next.js', level: '90', category: 'Frontend' },
    { id: 'sk3', name: 'Node.js / Express', level: '88', category: 'Backend' },
    { id: 'sk4', name: 'Python & Django', level: '82', category: 'Backend' },
    { id: 'sk5', name: 'PostgreSQL & MongoDB', level: '85', category: 'Database' },
    { id: 'sk6', name: 'Docker / Kubernetes', level: '80', category: 'DevOps' }
  ],
  projects: [
    {
      id: 'proj1',
      title: 'CloudMetrics Engine',
      link: 'https://github.com/alexmorgan/cloudmetrics',
      tech: 'Go, React, Prometheus, Grafana',
      description: 'Open-source lightweight server monitoring metrics visualizer with real-time WebSocket alerts.'
    }
  ],
  languages: [
    { id: 'lang1', name: 'English', level: 'Native / Bilingual' },
    { id: 'lang2', name: 'Spanish', level: 'Professional Working' }
  ],
  certifications: [
    { id: 'cert1', title: 'AWS Certified Solutions Architect – Professional', issuer: 'Amazon Web Services', date: '2022-11', url: 'https://aws.amazon.com' }
  ],
  socials: [
    { id: 'soc1', platform: 'GitHub', username: 'alexmorgan', url: 'https://github.com' },
    { id: 'soc2', platform: 'LinkedIn', username: 'in/alexmorgan-dev', url: 'https://linkedin.com' }
  ],
  references: [
    { id: 'ref1', name: 'Sarah Jenkins', title: 'VP of Engineering at TechCorp', contact: 'sarah.j@techcorp.com | (555) 987-6543' }
  ],
  hobbies: [
    { id: 'hob1', name: 'Open Source Contributing' },
    { id: 'hob2', name: 'Photography' }
  ],
  customSections: [
    {
      id: 'cust1',
      heading: 'Volunteer Work',
      items: [{ id: 'citem1', title: 'Coding Mentor', subtitle: 'Code.org', date: '2020 - Present', description: 'Volunteered 5 hours weekly teaching Web Development.' }]
    }
  ],
  settings: { template: 'modern', accentColor: '#2563eb', fontFamily: 'Inter', fontSize: '14px', margin: 'normal' }
};

function generateId() { return '_' + Math.random().toString(36).substr(2, 9); }

document.addEventListener('DOMContentLoaded', () => {
  loadFromLocalStorage();
  syncFormFields();
  renderAllLists();
  renderResume();
});

function saveToLocalStorage() {
  try { localStorage.setItem('goodbuilder_cv_data', JSON.stringify(resumeData)); } catch (e) {}
}

function loadFromLocalStorage() {
  try {
    const saved = localStorage.getItem('goodbuilder_cv_data');
    resumeData = saved ? JSON.parse(saved) : JSON.parse(JSON.stringify(sampleData));
  } catch (e) {
    resumeData = JSON.parse(JSON.stringify(sampleData));
  }
}

function loadSampleData() {
  if (confirm('Load sample data into Good Builder CV?')) {
    resumeData = JSON.parse(JSON.stringify(sampleData));
    syncFormFields();
    renderAllLists();
    renderResume();
    saveToLocalStorage();
  }
}

function clearData() {
  if (confirm('Clear all resume data?')) {
    resumeData = {
      personal: { fullName: '', jobTitle: '', email: '', phone: '', location: '', website: '', photo: '' },
      summary: '', experience: [], education: [], skills: [], projects: [], languages: [], certifications: [],
      socials: [], references: [], hobbies: [], customSections: [],
      settings: { template: 'modern', accentColor: '#2563eb', fontFamily: 'Inter', fontSize: '14px', margin: 'normal' }
    };
    syncFormFields();
    renderAllLists();
    renderResume();
    saveToLocalStorage();
  }
}

function exportJSON() {
  const dataStr = 'data:text/json;charset=utf-8,' + encodeURIComponent(JSON.stringify(resumeData, null, 2));
  const downloadAnchor = document.createElement('a');
  downloadAnchor.setAttribute('href', dataStr);
  downloadAnchor.setAttribute('download', `${(resumeData.personal.fullName || 'goodbuilder_cv').replace(/\s+/g, '_')}_data.json`);
  document.body.appendChild(downloadAnchor);
  downloadAnchor.click();
  downloadAnchor.remove();
}

function triggerImportJSON() { document.getElementById('json-input').click(); }

function importJSON(event) {
  const file = event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = (e) => {
    try {
      const imported = JSON.parse(e.target.result);
      if (imported && imported.personal) {
        resumeData = imported;
        syncFormFields();
        renderAllLists();
        renderResume();
        saveToLocalStorage();
        alert('Good Builder CV data imported!');
      }
    } catch (err) { alert('Error parsing JSON file.'); }
  };
  reader.readAsText(file);
}

function downloadPDF() {
  const element = document.getElementById('resume-preview');
  const filename = `${(resumeData.personal.fullName || 'Resume').replace(/\s+/g, '_')}_GoodBuilderCV.pdf`;
  const opt = {
    margin: 0,
    filename: filename,
    image: { type: 'jpeg', quality: 0.98 },
    html2canvas: { scale: 2, useCORS: true },
    jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
  };
  html2pdf().set(opt).from(element).save();
}

function switchTab(tabId) {
  document.querySelectorAll('.editor-tab-btn').forEach(btn => btn.classList.remove('active'));
  document.querySelectorAll('.tab-pane').forEach(pane => pane.classList.remove('active'));
  const selectedBtn = Array.from(document.querySelectorAll('.editor-tab-btn')).find(btn => btn.getAttribute('onclick').includes(tabId));
  if (selectedBtn) selectedBtn.classList.add('active');
  const selectedPane = document.getElementById(`tab-${tabId}`);
  if (selectedPane) selectedPane.classList.add('active');
}

function toggleMobileView() {
  const editor = document.getElementById('editor-panel');
  const btnText = document.getElementById('mobile-toggle-text');
  if (editor.style.display === 'none') {
    editor.style.display = 'flex';
    btnText.innerText = 'Preview Resume';
  } else {
    editor.style.display = 'none';
    btnText.innerText = 'Edit Resume';
  }
}

function syncFormFields() {
  document.getElementById('personal-fullName').value = resumeData.personal.fullName || '';
  document.getElementById('personal-jobTitle').value = resumeData.personal.jobTitle || '';
  document.getElementById('personal-email').value = resumeData.personal.email || '';
  document.getElementById('personal-phone').value = resumeData.personal.phone || '';
  document.getElementById('personal-location').value = resumeData.personal.location || '';
  document.getElementById('personal-website').value = resumeData.personal.website || '';
  document.getElementById('personal-photo').value = resumeData.personal.photo || '';
  document.getElementById('summary-text').value = resumeData.summary || '';

  document.getElementById('select-template').value = resumeData.settings.template || 'modern';
  document.getElementById('select-accent-color').value = resumeData.settings.accentColor || '#2563eb';
  document.getElementById('select-font').value = resumeData.settings.fontFamily || 'Inter';
  document.getElementById('select-font-size').value = resumeData.settings.fontSize || '14px';
  document.getElementById('select-margin').value = resumeData.settings.margin || 'normal';
}

function updatePersonalInfo() {
  resumeData.personal.fullName = document.getElementById('personal-fullName').value;
  resumeData.personal.jobTitle = document.getElementById('personal-jobTitle').value;
  resumeData.personal.email = document.getElementById('personal-email').value;
  resumeData.personal.phone = document.getElementById('personal-phone').value;
  resumeData.personal.location = document.getElementById('personal-location').value;
  resumeData.personal.website = document.getElementById('personal-website').value;
  resumeData.personal.photo = document.getElementById('personal-photo').value;
  saveToLocalStorage();
  renderResume();
}

function handlePhotoUpload(event) {
  const file = event.target.files[0];
  if (file) {
    const reader = new FileReader();
    reader.onload = (e) => {
      resumeData.personal.photo = e.target.result;
      document.getElementById('personal-photo').value = e.target.result;
      saveToLocalStorage();
      renderResume();
    };
    reader.readAsDataURL(file);
  }
}

function updateSummary() {
  resumeData.summary = document.getElementById('summary-text').value;
  saveToLocalStorage();
  renderResume();
}

function changeTemplate(val) { resumeData.settings.template = val; saveToLocalStorage(); renderResume(); }
function changeAccentColor(val) {
  resumeData.settings.accentColor = val;
  document.getElementById('select-accent-color').value = val;
  saveToLocalStorage();
  renderResume();
}
function changeFontFamily(val) { resumeData.settings.fontFamily = val; saveToLocalStorage(); renderResume(); }
function changeFontSize(val) { resumeData.settings.fontSize = val; saveToLocalStorage(); renderResume(); }
function changeMargin(val) { resumeData.settings.margin = val; saveToLocalStorage(); renderResume(); }

// RENDER FORM EDITOR LISTS
function renderExperienceList() {
  const container = document.getElementById('experience-list');
  container.innerHTML = '';
  resumeData.experience.forEach((item, index) => {
    const card = document.createElement('div');
    card.className = 'entry-card';
    card.innerHTML = `
      <div class="entry-card-header">
        <span class="entry-card-title">${item.title || 'Role'} at ${item.company || 'Company'}</span>
        <div class="entry-actions">
          <button class="btn btn-outline btn-sm" onclick="moveItem('experience', ${index}, -1)"><i class="fa-solid fa-arrow-up"></i></button>
          <button class="btn btn-outline btn-sm" onclick="moveItem('experience', ${index}, 1)"><i class="fa-solid fa-arrow-down"></i></button>
          <button class="btn btn-danger btn-sm" onclick="removeItem('experience', '${item.id}')"><i class="fa-solid fa-trash"></i></button>
        </div>
      </div>
      <div class="form-group"><label>Job Title</label><input type="text" value="${escapeAttr(item.title)}" oninput="updateItemField('experience', '${item.id}', 'title', this.value)"/></div>
      <div class="form-row">
        <div class="form-group"><label>Company</label><input type="text" value="${escapeAttr(item.company)}" oninput="updateItemField('experience', '${item.id}', 'company', this.value)"/></div>
        <div class="form-group"><label>Location</label><input type="text" value="${escapeAttr(item.location)}" oninput="updateItemField('experience', '${item.id}', 'location', this.value)"/></div>
      </div>
      <div class="form-row">
        <div class="form-group"><label>Start Date</label><input type="month" value="${item.startDate || ''}" oninput="updateItemField('experience', '${item.id}', 'startDate', this.value)" onchange="updateItemField('experience', '${item.id}', 'startDate', this.value)"/></div>
