function addCustomSection() { resumeData.customSections.push({ id: generateId(), heading: 'Custom Section', items: [] }); renderCustomSectionsList(); saveToLocalStorage(); renderResume(); }
function removeCustomSection(secId) { resumeData.customSections = resumeData.customSections.filter(s => s.id !== secId); renderCustomSectionsList(); saveToLocalStorage(); renderResume(); }
function updateCustomHeading(secId, val) { const sec = resumeData.customSections.find(s => s.id === secId); if (sec) sec.heading = val; saveToLocalStorage(); renderResume(); }

function addCustomItem(secId) {
  const sec = resumeData.customSections.find(s => s.id === secId);
  if (sec) {
    sec.items.push({ id: generateId(), title: '', subtitle: '', date: '', description: '' });
    renderCustomSectionsList(); saveToLocalStorage(); renderResume();
  }
}

function removeCustomItem(secId, itemId) {
  const sec = resumeData.customSections.find(s => s.id === secId);
  if (sec) {
    sec.items = sec.items.filter(i => i.id !== itemId);
    renderCustomSectionsList(); saveToLocalStorage(); renderResume();
  }
}

function updateCustomItemField(secId, itemId, field, val) {
  const sec = resumeData.customSections.find(s => s.id === secId);
  if (sec) {
    const item = sec.items.find(i => i.id === itemId);
    if (item) item[field] = val;
    saveToLocalStorage(); renderResume();
  }
}

function renderAllLists() {
  renderExperienceList(); renderEducationList(); renderSkillsList(); renderProjectsList();
  renderLanguagesList(); renderCertificationsList(); renderSocialsList(); renderReferencesList();
  renderHobbiesList(); renderCustomSectionsList();
}

function updateItemField(category, id, field, val) {
  const item = resumeData[category].find(i => i.id === id);
  if (item) { item[field] = val; saveToLocalStorage(); renderResume(); }
}

function removeItem(category, id) {
  resumeData[category] = resumeData[category].filter(i => i.id !== id);
  renderAllLists(); saveToLocalStorage(); renderResume();
}

function moveItem(category, index, direction) {
  const arr = resumeData[category];
  const targetIndex = index + direction;
  if (targetIndex >= 0 && targetIndex < arr.length) {
    const temp = arr[index]; arr[index] = arr[targetIndex]; arr[targetIndex] = temp;
    renderAllLists(); saveToLocalStorage(); renderResume();
  }
}

function escapeAttr(str) { return str ? str.replace(/"/g, '&quot;').replace(/'/g, '&#39;') : ''; }
function formatDate(dateStr) {
  if (!dateStr) return '';
  const [year, month] = dateStr.split('-');
  if (!year) return dateStr;
  if (!month) return year;
  const date = new Date(year, month - 1);
  return date.toLocaleString('default', { month: 'short' }) + ' ' + year;
}

// SECTION RENDER HELPERS
function getSectionHTML(title, content) {
  if (!content) return '';
  return `<div style="margin-bottom:1.25rem;">
    <h3 style="color:var(--accent-color); font-size:1.05rem; font-weight:700; border-bottom:2px solid var(--accent-color); padding-bottom:3px; margin-bottom:0.6rem; text-transform:uppercase;">${title}</h3>
    ${content}
  </div>`;
}

function renderCommonExperience() {
  if (!resumeData.experience.length) return '';
  return resumeData.experience.map(e => `
    <div style="margin-bottom:0.85rem;">
      <div style="display:flex; justify-content:space-between; font-weight:700;">
        <span style="color:#0f172a;">${e.title}</span>
        <span style="color:var(--accent-color); font-size:0.8rem;">${formatDate(e.startDate)}${e.startDate || e.endDate || e.current ? ' - ' : ''}${e.current ? 'Present' : formatDate(e.endDate)}</span>
      </div>
      <div style="font-size:0.85rem; color:#475569; font-weight:500;">${e.company} ${e.location ? `• ${e.location}` : ''}</div>
      <div style="font-size:0.85rem; color:#334155; margin-top:0.25rem; white-space:pre-line;">${e.description}</div>
    </div>
  `).join('');
}

