  if (!resumeData.customSections || !resumeData.customSections.length) return '';
  return resumeData.customSections.map(sec => {
    if (!sec.items || !sec.items.length) return '';
    const itemsHTML = sec.items.map(i => `
      <div style="margin-bottom:0.6rem;">
        <div style="display:flex; justify-content:space-between; font-weight:700;"><span>${i.title}</span><span style="color:#64748b; font-size:0.8rem;">${i.date}</span></div>
        ${i.subtitle ? `<div style="font-size:0.85rem; color:#475569;">${i.subtitle}</div>` : ''}
        ${i.description ? `<div style="font-size:0.85rem; color:#334155;">${i.description}</div>` : ''}
      </div>
    `).join('');
    return getSectionHTML(sec.heading, itemsHTML);
  }).join('');
}

// MAIN RESUME RENDER ENGINE
function renderResume() {
  const container = document.getElementById('resume-preview');
  const settings = resumeData.settings;
  const p = resumeData.personal;

  let paddingMap = { compact: '1.5rem', normal: '2.5rem', spacious: '3.5rem' };
  const paddingVal = paddingMap[settings.margin] || '2.5rem';

  container.style.fontFamily = `'${settings.fontFamily}', sans-serif`;
  container.style.fontSize = settings.fontSize || '14px';
  container.style.setProperty('--accent-color', settings.accentColor || '#2563eb');

  const template = settings.template || 'modern';
  let html = '';

  if (template === 'modern') html = renderModernTemplate(p, paddingVal);
  else if (template === 'classic') html = renderClassicTemplate(p, paddingVal);
  else if (template === 'minimal') html = renderMinimalTemplate(p, paddingVal);
  else if (template === 'creative') html = renderCreativeTemplate(p, paddingVal);
  else if (template === 'compact') html = renderCompactTemplate(p, paddingVal);
  else if (template === 'executive') html = renderExecutiveTemplate(p, paddingVal);
  else if (template === 'serif') html = renderSerifTemplate(p, paddingVal);
  else if (template === 'timeline') html = renderTimelineTemplate(p, paddingVal);

  container.innerHTML = html;
}

function renderModernTemplate(p, padding) {
  return `
    <div class="template-modern">
      <div class="sidebar">
        ${p.photo ? `<img src="${p.photo}" class="profile-img" alt="Profile"/>` : ''}
        <div style="font-size:1.4rem; font-weight:700; text-align:center;">${p.fullName || 'Your Name'}</div>
        <div style="font-size:0.85rem; text-align:center; opacity:0.8; margin-bottom:1.5rem;">${p.jobTitle || 'Profession'}</div>
        <div style="font-size:0.8rem; margin-bottom:1.25rem;">
          ${p.email ? `<div style="margin-bottom:0.35rem;"><i class="fa-solid fa-envelope"></i> ${p.email}</div>` : ''}
          ${p.phone ? `<div style="margin-bottom:0.35rem;"><i class="fa-solid fa-phone"></i> ${p.phone}</div>` : ''}
          ${p.location ? `<div style="margin-bottom:0.35rem;"><i class="fa-solid fa-location-dot"></i> ${p.location}</div>` : ''}
          ${p.website ? `<div style="margin-bottom:0.35rem;"><i class="fa-solid fa-globe"></i> ${p.website}</div>` : ''}
        </div>

        ${resumeData.skills.length ? `<div style="margin-bottom:1.25rem;"><div style="font-weight:700; text-transform:uppercase; border-bottom:1px solid rgba(255,255,255,0.3); padding-bottom:2px; margin-bottom:0.5rem;">Skills</div>${resumeData.skills.map(s => `<div style="font-size:0.8rem; margin-bottom:0.25rem;">${s.name} (${s.level}%)</div>`).join('')}</div>` : ''}
        ${resumeData.languages.length ? `<div style="margin-bottom:1.25rem;"><div style="font-weight:700; text-transform:uppercase; border-bottom:1px solid rgba(255,255,255,0.3); padding-bottom:2px; margin-bottom:0.5rem;">Languages</div>${resumeData.languages.map(l => `<div style="font-size:0.8rem; margin-bottom:0.25rem;">${l.name} (${l.level})</div>`).join('')}</div>` : ''}
        ${resumeData.hobbies.length ? `<div><div style="font-weight:700; text-transform:uppercase; border-bottom:1px solid rgba(255,255,255,0.3); padding-bottom:2px; margin-bottom:0.5rem;">Hobbies</div><div style="display:flex; flex-wrap:wrap; gap:0.25rem;">${resumeData.hobbies.map(h => `<span style="background:rgba(255,255,255,0.2); padding:2px 6px; border-radius:10px; font-size:0.75rem;">${h.name}</span>`).join('')}</div></div>` : ''}
      </div>
      <div class="main-content">
        ${resumeData.summary ? getSectionHTML('Profile Summary', `<p style="margin:0; color:#334155;">${resumeData.summary}</p>`) : ''}
        ${getSectionHTML('Work Experience', renderCommonExperience())}
        ${getSectionHTML('Education', renderCommonEducation())}
        ${getSectionHTML('Projects', renderCommonProjects())}
        ${getSectionHTML('Certifications', renderCommonCertifications())}
        ${getSectionHTML('References', renderCommonReferences())}
        ${renderCommonCustom()}
      </div>
    </div>
  `;
}

function renderClassicTemplate(p, padding) {
  return `
    <div class="template-classic" style="padding:${padding};">
      <div class="header-classic">
        <div class="name-classic">${p.fullName || 'YOUR NAME'}</div>
        <div style="font-size:1.1rem; font-weight:600; color:#475569;">${p.jobTitle || 'PROFESSIONAL TITLE'}</div>
        <div style="margin-top:0.5rem; font-size:0.85rem; color:#64748b;">${p.email || ''} • ${p.phone || ''} • ${p.location || ''} • ${p.website || ''}</div>
      </div>
      ${resumeData.summary ? getSectionHTML('Executive Summary', `<p>${resumeData.summary}</p>`) : ''}
      ${getSectionHTML('Work Experience', renderCommonExperience())}
      ${getSectionHTML('Education', renderCommonEducation())}
      ${getSectionHTML('Skills & Competencies', renderCommonSkills())}
      ${getSectionHTML('Projects', renderCommonProjects())}
      ${getSectionHTML('Languages', renderCommonLanguages())}
      ${getSectionHTML('Certifications', renderCommonCertifications())}
      ${getSectionHTML('References', renderCommonReferences())}
      ${renderCommonCustom()}
    </div>
  `;
}

function renderMinimalTemplate(p, padding) {
