        <div style="text-align:right; font-size:0.85rem; color:#64748b;">${p.email || ''}<br/>${p.phone || ''}<br/>${p.location || ''}</div>
      </div>
      ${resumeData.summary ? `<p style="margin-bottom:1.5rem; color:#334155;">${resumeData.summary}</p>` : ''}
      ${getSectionHTML('Experience', renderCommonExperience())}
      ${getSectionHTML('Education', renderCommonEducation())}
      ${getSectionHTML('Skills', renderCommonSkills())}
      ${getSectionHTML('Projects', renderCommonProjects())}
      ${getSectionHTML('Certifications', renderCommonCertifications())}
      ${renderCommonCustom()}
    </div>
  `;
}

